// SPL2LexerInit initializes any static state used to implement SPL2Lexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewSPL2Lexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func SPL2LexerInit() {
	staticData := &SPL2LexerLexerStaticData
	staticData.once.Do(spl2lexerLexerInit)
}

// NewSPL2Lexer produces a new lexer instance for the optional input antlr.CharStream.
func NewSPL2Lexer(input antlr.CharStream) *SPL2Lexer {
	SPL2LexerInit()
	l := new(SPL2Lexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &SPL2LexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "SPL2Lexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

